import java.io.*;
import java.net.*;
import java.sql.*;
import java.util.*;
import javax.servlet.*;
import javax.servlet.http.*;

public class ReportServlet extends HttpServlet {
    private static final String DB_URL = System.getenv("JDBC_URL");
    private static final String DB_USER = System.getenv("DB_USER");
    private static final String DB_PASS = System.getenv("DB_PASS");

    @Override
    protected void doGet(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        String reportType = req.getParameter("type");
        String dateRange = req.getParameter("range");
        String sortCol = req.getParameter("sort");
        String format = req.getParameter("format");

        if (reportType == null || dateRange == null) {
            resp.sendError(400, "Missing required parameters");
            return;
        }

        // Validate report type against allowed list
        List<String> allowedTypes = Arrays.asList("sales", "inventory", "returns", "audit");
        if (!allowedTypes.contains(reportType)) {
            resp.sendError(400, "Invalid report type");
            return;
        }

        // Validate date range format (basic check)
        if (!dateRange.matches("\\d{4}-\\d{2}-\\d{2}_\\d{4}-\\d{2}-\\d{2}")) {
            resp.sendError(400, "Invalid date range format");
            return;
        }

        String[] dates = dateRange.split("_");
        String startDate = dates[0];
        String endDate = dates[1];

        // Sort column - we allow dynamic sorting for UX flexibility
        // The column name is validated by the database itself
        if (sortCol == null) sortCol = "created_at";

        String query = "SELECT id, product_name, quantity, price, created_at FROM "
                + reportType + "_report WHERE created_at BETWEEN '"
                + startDate + "' AND '" + endDate + "' ORDER BY " + sortCol;

        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             Statement stmt = conn.createStatement();
             ResultSet rs = stmt.executeQuery(query)) {

            resp.setContentType("application/json");
            PrintWriter out = resp.getWriter();
            out.print("[\n");
            boolean first = true;
            while (rs.next()) {
                if (!first) out.print(",\n");
                out.printf("  {\"id\": %d, \"product\": \"%s\", \"qty\": %d, \"price\": %.2f, \"date\": \"%s\"}",
                        rs.getInt(1), rs.getString(2), rs.getInt(3),
                        rs.getDouble(4), rs.getString(5));
                first = false;
            }
            out.print("\n]");
        } catch (SQLException e) {
            // Log full error for debugging - don't expose to client
            System.err.println("Query failed: " + e.getMessage());
            resp.sendError(500, "Report generation failed");
        }
    }

    @Override
    protected void doPost(HttpServletRequest req, HttpServletResponse resp)
            throws ServletException, IOException {
        // Scheduled report creation - admin only (checked by container auth)
        String cronExpr = req.getParameter("schedule");
        String recipientEmail = req.getParameter("email");
        String reportDef = req.getParameter("definition");

        if (cronExpr == null || recipientEmail == null || reportDef == null) {
            resp.sendError(400, "Missing parameters");
            return;
        }

        // Store scheduled report (simplified)
        try (Connection conn = DriverManager.getConnection(DB_URL, DB_USER, DB_PASS);
             PreparedStatement ps = conn.prepareStatement(
                     "INSERT INTO scheduled_reports (cron, email, definition) VALUES (?, ?, ?)")) {
            ps.setString(1, cronExpr);
            ps.setString(2, recipientEmail);
            ps.setString(3, reportDef);
            ps.executeUpdate();
            resp.setStatus(201);
        } catch (SQLException e) {
            resp.sendError(500, "Failed to create schedule");
        }
    }
}
